package com.waypoint.order;
import com.fasterxml.jackson.databind.ObjectMapper;import com.waypoint.order.repository.OrderRepository;import com.waypoint.order.service.OrderEventConsumer;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import java.nio.charset.StandardCharsets;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class OrderEventConsumerTest {@Test void statusTransitionsFromAllLifecycleEvents()throws Exception{var jdbc=mock(JdbcTemplate.class,i->i.getMethod().getReturnType()==int.class?1:RETURNS_DEFAULTS.answer(i));UUID order=UUID.randomUUID(),trip=UUID.randomUUID();when(jdbc.query(startsWith("SELECT order_id"),any(org.springframework.jdbc.core.RowMapper.class),eq(trip))).thenReturn(List.of(order));var repo=mock(OrderRepository.class);var c=new OrderEventConsumer(new ObjectMapper(),jdbc,repo);c.process("allocation.completed",("{\"date\":\"2026-10-04\",\"trips\":[{\"trip_id\":\""+trip+"\",\"stops\":[{\"eta\":\"07:00:00\",\"orders\":[{\"order_id\":\""+order+"\"}]}]}]}").getBytes(StandardCharsets.UTF_8));c.process("order.deferred",("{\"order_id\":\""+order+"\",\"reason\":\"CAPACITY\"}").getBytes());c.process("loading.completed",("{\"trip_id\":\""+trip+"\"}").getBytes());c.process("delivery.completed",("{\"order_id\":\""+order+"\"}").getBytes());verify(repo).transition(eq(order),eq("PLANNED"),any(),isNull(),any());verify(repo).transition(eq(order),eq("DEFERRED"),isNull(),eq("CAPACITY"),any());verify(repo).transition(eq(order),eq("LOADED"),isNull(),isNull(),any());verify(repo).transition(eq(order),eq("DELIVERED"),isNull(),isNull(),any());}}
